<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Appointments | HMS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
:root{--bg:#091b35;--panel:#122b50;--raised:#1b3964;--line:#2c4770;--gold:#edbd3f;--muted:#bdc8db;--red:#ef9297;--green:#75dda6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#fff;font:14px 'DM Sans',sans-serif}.wrap{max-width:1400px;margin:auto;padding:25px 27px 45px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}h1,h2{font-family:Manrope,sans-serif}h1{margin:0;font-size:29px}h2{margin:0;font-size:15px}.sub,.note{color:var(--muted)}.sub{margin:6px 0}.back{color:var(--gold);text-decoration:none;border:1px solid var(--line);padding:10px 14px;border-radius:8px}.banner{padding:12px 15px;margin-bottom:15px;border:1px solid var(--gold);border-radius:8px;color:var(--gold);background:#2d2715}.error{border-color:var(--red);color:#ffd8da}.grid{display:grid;grid-template-columns:.72fr 1.28fr;gap:16px}.card{overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.head{padding:15px 16px;border-bottom:1px solid var(--line)}.head i{color:var(--gold);margin-right:8px}.body{padding:16px}form label{display:grid;gap:6px;margin-bottom:11px;color:var(--muted);font-size:12px}input,select,textarea{width:100%;min-height:40px;padding:8px 10px;border:1px solid #466387;border-radius:7px;background:#0c2446;color:#fff;font:inherit}textarea{min-height:70px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:11px}button{min-height:40px;padding:0 13px;border:0;border-radius:7px;background:var(--gold);color:#12284a;font-weight:800;cursor:pointer}.table{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse;font-size:12px}th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{background:var(--raised);color:var(--gold);font-size:11px}td small{display:block;margin-top:3px;color:var(--muted)}.badge{display:inline-flex;padding:4px 8px;border-radius:999px;background:var(--gold);color:#11294c;font-size:10px;font-weight:800}.badge.waiting{background:#f5ce83}.badge.cancelled{background:var(--red);color:#fff}.badge.confirmed{background:var(--green);color:#123a29}.inline{display:flex;gap:7px;align-items:center}.inline select,.inline button{min-height:31px;padding:4px 8px;font-size:11px}.detail{white-space:normal;min-width:190px;color:#dce6f4;line-height:1.45}.live{color:var(--green);font-size:11px}.empty{text-align:center;color:var(--muted);padding:20px}@media(max-width:950px){.grid{grid-template-columns:1fr}}@media(max-width:560px){.wrap{padding:17px 12px}.top{align-items:flex-start;flex-direction:column}.row{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><header class="top"><div><h1><i class="fa-solid fa-calendar-check" style="color:var(--gold)"></i> Appointments</h1><p class="sub">Book appointments and monitor every patient visit in real time.</p></div><a class="back" href="{{ url('/') }}"><i class="fa-solid fa-arrow-left"></i> Dashboard</a></header>@if(session('status'))<div class="banner"><i class="fa-solid fa-circle-check"></i> {{ session('status') }}</div>@endif @if($errors->any())<div class="banner error"><i class="fa-solid fa-triangle-exclamation"></i> {{ $errors->first() }}</div>@endif
<section class="grid"><article class="card"><div class="head"><h2><i class="fa-solid fa-calendar-plus"></i>Book new appointment</h2></div><div class="body"><p class="note">Choose an existing patient or enter new patient details. A token is reserved automatically for the selected date.</p><form method="POST" action="{{ route('receptionist.appointments.store') }}">@csrf<label>Existing patient<select name="patient_id"><option value="">New patient</option>@foreach($patients as $patient)<option value="{{ $patient->id }}">{{ $patient->patient_code }} · {{ $patient->name }}</option>@endforeach</select></label><div class="row"><label>New patient name<input name="patient_name" placeholder="Patient name"></label><label>Phone<input name="phone" placeholder="Phone number"></label></div><div class="row"><label>Gender<select name="gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Age<input type="number" name="age" min="0" max="130"></label></div><label>Doctor<select name="doctor_id" required><option value="">Select doctor</option>@foreach($doctors as $doctor)<option value="{{ $doctor->id }}">{{ $doctor->name }} · {{ $doctor->specialty }} @if($doctor->room)(Room {{ $doctor->room }})@endif</option>@endforeach</select></label><div class="row"><label>Date<input type="date" name="appointment_date" value="{{ now()->toDateString() }}" required></label><label>Time<input type="time" name="appointment_time" required></label></div><div class="row"><label>Department<input name="department" placeholder="Cardiology"></label><label>Visit type<select name="type"><option>Consultation</option><option>Follow-up</option><option>Emergency</option></select></label></div><label>Reason<input name="reason" placeholder="Reason for visit"></label><label>Notes<textarea name="notes" placeholder="Additional information"></textarea></label><button><i class="fa-solid fa-calendar-check"></i> Confirm appointment</button></form></div></article>
<article class="card"><div class="head"><h2><i class="fa-solid fa-list-check"></i>Appointment details <span class="live">● Live updates every 15 seconds</span></h2></div><div class="table"><table><thead><tr><th>Patient</th><th>Doctor</th><th>Schedule</th><th>Visit detail</th><th>Status</th><th>Manage</th></tr></thead><tbody id="appointmentsBody">@forelse($appointments as $appointment)<tr><td><strong>{{ $appointment->patient->name }}</strong><small>{{ $appointment->patient->patient_code }} · {{ $appointment->patient->phone ?: 'No phone' }}</small></td><td>{{ $appointment->doctor->name }}<small>{{ $appointment->doctor->specialty }}</small></td><td>{{ $appointment->appointment_date->format('d M Y') }}<small>{{ \Illuminate\Support\Carbon::parse($appointment->appointment_time)->format('h:i A') }}</small></td><td class="detail">{{ $appointment->department ?: 'General' }} · {{ $appointment->type ?: 'Visit' }}<br>{{ $appointment->reason ?: 'No reason entered' }}</td><td><span class="badge {{ strtolower($appointment->status) }}">{{ $appointment->status }}</span></td><td><form class="inline" method="POST" action="{{ route('receptionist.appointments.status', $appointment) }}">@csrf @method('PATCH')<select name="status"><option @selected($appointment->status === 'Confirmed')>Confirmed</option><option @selected($appointment->status === 'Waiting')>Waiting</option><option @selected($appointment->status === 'Cancelled')>Cancelled</option></select><button type="submit">Save</button></form></td></tr>@empty<tr><td colspan="6" class="empty">No appointments booked yet.</td></tr>@endforelse</tbody></table></div></article></section></main><script>
const body=document.getElementById('appointmentsBody');function esc(value){const el=document.createElement('span');el.textContent=value ?? '';return el.innerHTML}async function refreshAppointments(){try{const response=await fetch('{{ route('receptionist.appointments.live') }}',{headers:{Accept:'application/json'}});if(!response.ok)return;const appointments=await response.json();body.innerHTML=appointments.length?appointments.map(a=>`<tr><td><strong>${esc(a.patient?.name)}</strong><small>${esc(a.patient?.patient_code)} · ${esc(a.patient?.phone||'No phone')}</small></td><td>${esc(a.doctor?.name)}<small>${esc(a.doctor?.specialty)}</small></td><td>${esc(a.appointment_date)}<small>${esc(a.appointment_time)}</small></td><td class="detail">${esc(a.department||'General')} · ${esc(a.type||'Visit')}<br>${esc(a.reason||'No reason entered')}</td><td><span class="badge ${String(a.status).toLowerCase()}">${esc(a.status)}</span></td><td>Refresh page to manage</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No appointments booked yet.</td></tr>'}catch(error){}}setInterval(refreshAppointments,15000);
</script></body></html>